cd /workspace && rm src/invoiceAmount.ts src/reportAmount.ts && cat > src/money.ts <<'EOF'
/**
 * Shared cent-to-string conversion.
 *
 * Returns the sign (for negative amounts, only ever a single leading '-'),
 * the absolute whole currency units and exactly two fraction digits with no
 * currency symbol. Rounding/behaviour matches the original
 * invoiceAmount/reportAmount implementations exactly.
 */
export function formatAmount(cents: number): string {
  const absolute = Math.abs(cents);
  const sign = cents < 0 ? '-' : '';
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
grep -rnw 'invoiceAmount\|reportAmount' src/ README.md checks/ || echo "no stale references"
tsc -p tsconfig.json && node checks/public.cjs

